script:
(function () {
  'use strict';
  // HSA goal: the level yearly contribution (paid in 12 equal monthly amounts) needed to reach a
  // target balance. Monthly steps, with i = (1 + annual return)^(1/12) - 1:
  //   balance = balance x (1 + i) + (your contribution + employer contribution) / 12
  //             - medical expenses paid that month (never more than the balance)
  // Monthly expenses rise once a year by the expense inflation rate; any amount above the balance
  // is paid out of pocket. The required contribution is found by bisection on that simulation.
  // With no expenses it equals the closed form
  //   C = 12 x (target - B(1 + i)^N - E/12 x s) / s,  s = ((1 + i)^N - 1) / i,  N = 12 x years.
  // CHECKS (Node, scratch tests): $0 start, $50,000 in 20 years at 0% -> $2,500/yr; $2,000 start,
  // $50,000 in 20 years at 5%, $500 employer, no expenses -> closed form C = $821.62 a year matches the bisection to
  // within $0.01; target already reachable from the balance -> $0; $100/month expenses at 0% add
  // $1,200/yr; 2026 room = $4,400 - $500 = $3,900 self-only ($4,900 at 55+).
  // ---- 2026 HSA LIMITS (calendar year 2026) ---------------------------------------------------
  // Source: IRS Rev. Proc. 2025-19 (IRC 223 inflation adjustments for 2026). Catch-up: IRC
  // 223(b)(3)(B), a fixed $1,000 for account holders 55 or older (not indexed; IRS Pub. 969).
  var HSA = {
    year: 2026,
    limit: { self: 4400, family: 8750 },
    catchUp55: 1000
  };
  // --------------------------------------------------------------------------------------------

  // p: balance, years, ret, employer, expenses (monthly), costRise (decimals); c = your yearly contribution
  function simulate(p, c) {
    var i = Math.pow(1 + p.ret, 1 / 12) - 1, bal = p.balance, rows = [], paid = 0, oop = 0, inTot = 0;
    var yIn = 0, yPaid = 0, yGrowth = 0;
    for (var m = 1; m <= p.years * 12; m++) {
      var y = Math.floor((m - 1) / 12);
      var g = bal * i;
      bal += g + (c + p.employer) / 12;
      var exp = p.expenses * Math.pow(1 + p.costRise, y), pay = Math.min(exp, Math.max(0, bal));
      bal -= pay; paid += pay; oop += exp - pay; inTot += (c + p.employer) / 12;
      yIn += (c + p.employer) / 12; yPaid += pay; yGrowth += g;
      if (m % 12 === 0) {
        rows.push({ year: m / 12, inflow: yIn, paid: yPaid, growth: yGrowth, balance: bal });
        yIn = 0; yPaid = 0; yGrowth = 0;
      }
    }
    return { balance: bal, rows: rows, paid: paid, oop: oop, inTot: inTot, growth: bal - p.balance - inTot + paid };
  }

  function required(p) {
    if (simulate(p, 0).balance >= p.target - 0.005) return 0;
    var lo = 0, hi = 1000;
    while (simulate(p, hi).balance < p.target && hi < 1e10) hi *= 2;
    for (var k = 0; k < 100; k++) {
      var mid = (lo + hi) / 2;
      if (simulate(p, mid).balance < p.target) lo = mid; else hi = mid;
    }
    return hi;
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var coverage = document.getElementById('hgCoverage').value, age55 = document.getElementById('hgAge55').checked;
    var balance = num('hgBalance'), target = num('hgTarget'), years = Math.round(num('hgYears')), ret = num('hgRate'),
        employer = num('hgEmployer'), expenses = num('hgExpenses'), costRise = num('hgCostRise');
    var error = document.getElementById('hgError');
    var all = [balance, target, years, ret, employer, expenses, costRise];
    var msg = '';
    if (all.some(isNaN) || all.some(function (v) { return v < 0; })) msg = 'Enter non-negative numbers in every field.';
    else if (target <= 0) msg = 'Enter a savings goal above $0.';
    else if (years < 1 || years > 60) msg = 'Enter 1 to 60 years.';
    else if (ret > 30 || costRise > 20) msg = 'Enter a return up to 30% and an expense increase up to 20%.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }
    var p = { balance: balance, target: target, years: years, ret: ret / 100, employer: employer,
              expenses: expenses, costRise: costRise / 100 };
    var c = required(p), r = simulate(p, c);
    var lim = HSA.limit[coverage] + (age55 ? HSA.catchUp55 : 0), room = Math.max(0, lim - employer);
    set('hgYearly', money(c));
    set('hgMonthly', money(c / 12));
    set('hgYouTotal', money(c * years));
    set('hgEmpTotal', money(employer * years));
    set('hgPaid', money(r.paid));
    set('hgGrowth', money(r.growth));
    set('hgRoom', HSA.year + ' limit for ' + (coverage === 'family' ? 'family' : 'self-only') + ' coverage' +
        (age55 ? ' with the 55+ catch-up' : '') + ': ' + money(lim) + '. After your employer\'s ' + money(Math.min(employer, lim)) +
        ', you can put in up to ' + money(room) + ' a year.');
    var over = document.getElementById('hgOver');
    var tooHigh = c > room + 0.5 || employer > lim + 0.5;
    over.hidden = !tooHigh;
    if (tooHigh) {
      var atMax = simulate(p, room).balance;
      over.textContent = 'This is more than the ' + HSA.year + ' limit allows. Contributing the most you can (' + money(room) +
          ' a year) would reach about ' + money(atMax) + '. Limits usually rise with inflation, so later years may allow more.';
    }
    var oopEl = document.getElementById('hgOop');
    oopEl.hidden = !(r.oop > 0.5);
    if (r.oop > 0.5) oopEl.textContent = 'In some months your expenses are larger than the balance, so about ' +
        money(r.oop) + ' would be paid from other money.';
    var body = document.getElementById('hgSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, money(row.inflow), money(row.paid), money(row.growth), money(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
